//! **What the dispatcher can do, and what it cannot.**
//!
//! `FILTER_ARM_PROGS` is generated by `build.rs` from the arms of the `match`:
//! it is the EXACT set of named programs, not a hand-rewritten list that would
//! drift at the first added arm. Enough to answer "is this command covered?"
//! without lying, and to name a route that is not.

use super::*;

pub fn program_basename(argv: &[String]) -> String {
    let i = program_index(argv);
    match argv.get(i) {
        // `(cd x && make)`: the paren opening a subshell is glued to its first word.
        Some(tok) => basename(
            tok.trim_matches(|c| c == '\'' || c == '"')
                .trim_start_matches('('),
        ),
        None => String::new(),
    }
}

/// Index of the real program token in `argv`, after scaffolding and wrappers.
///
/// Split out of [`program_basename`] so callers that need the program's
/// ARGUMENTS get the same slice the router uses. `uncovered_route_name` did
/// not: it resolved the program correctly and then asked `find_subcommand`
/// about the WHOLE argv, so `cd x && git status` produced the route name
/// `"git ."` — the `cd` argument read as git's subcommand. That name is what
/// the coverage-gap counters key on, which is how `~/.tokenade/cmdstats` came
/// to hold entries that are not commands at all.
pub(super) fn program_index(argv: &[String]) -> usize {
    let mut i = 0;
    loop {
        // Skip env-assignment tokens, a `cd … &&` prefix and any bash
        // control-flow header, exactly as `setup_filter_state` does — the
        // shared resolver is what keeps label and route in agreement.
        i = skip_shell_scaffolding(argv, i);
        let Some(tok) = argv.get(i) else {
            return argv.len();
        };
        // Fleet-data fix: quoted program names ('python3') recorded as a
        // distinct command — strip shell quotes before basenaming.
        let tok = tok.trim_matches(|c| c == '\'' || c == '"');
        let name = basename(tok);
        // Unwrap one wrapper level and re-resolve, mirroring
        // `filter_wrapped`'s `argv.iter().skip(1)`.
        if is_wrapper_prog(&name) {
            i += 1;
            // Fleet-data fix: a wrapper's own leading flags (`sudo -p x`)
            // were returned as the "command" (`-p`).
            //
            // Second fleet-data fix (2026-08, from `~/.tokenade/cmdstats`):
            // several wrappers take a bare NUMBER before the program —
            // `timeout 300 cargo test`, `nice -n 10 cargo test`,
            // `timeout -k 5 120 pytest` — and that number was returned as the
            // command. Cost was not cosmetic: compactor dispatch keys on this
            // name, so every `timeout N <cmd>` lost its dedicated compactor and
            // fell through to generic folding — on exactly the long-running
            // commands an agent puts a timeout on, i.e. the ones with the most
            // output. It also polluted the telemetry that decides where a
            // compactor is missing: the counters showed `300`, `200`, `115` as
            // if they were programs.
            //
            // The rule is general rather than per-wrapper: in the program
            // position, a token that is only digits (with an optional decimal
            // part and an optional s/m/h/d suffix) is a duration or a priority,
            // never an executable. `7z` and `2to3` start with a digit and are
            // correctly NOT matched.
            //
            // Third fleet-data fix (2026-08-28): a flag's VALUE is not a
            // program either. See [`skip_wrapper_prefix`], which both this and
            // `filter_wrapped` now share.
            i = skip_wrapper_prefix(&name, argv, i);
            continue;
        }
        return i;
    }
}

// ─────────────────────────────────────────────────────────────────────
// argv inspection helpers (used by variant-aware compactors)
// ─────────────────────────────────────────────────────────────────────
//
// Compactors take an `argv: &[String]` slice and need to ask three
// kinds of questions about it:
//   1. "is this exact token present?"           → has_flag
//   2. "is one of these tokens present?"        → has_any_flag
//   3. "what value follows --flag / --flag=X?"  → flag_value
//
// `flag_value` handles both shapes — Cargo, git, kubectl etc. all
// accept both forms (`--message-format=json` and `--message-format
// json`). Returning the FIRST match means a caller-passed override
// later in argv wins (matches CLI argument semantics).

/// True iff tokenade has a dedicated compaction route for program `prog`.
/// Pure name lookup — never runs a compactor.
///
/// All three sources are derived from code, never hand-listed:
///   1. the explicit family arms of [`filter_command`] (git, cargo, kubectl,
///      docker, …) — extracted from this file's source by build.rs;
///   2. the per-command compactor modules under `cmd/{linux,macos,windows}/`
///      — the build.rs auto-dispatch table;
///   3. the alias-only names handled inside `cmd::dispatch_named`
///      ([`crate::cmd::NAMED_EXTRA_PROGS`]).
///
/// Adding a compactor (a new module file or a new filter arm) therefore
/// updates this predicate on the next build with no list to maintain.
pub fn knows_program(prog: &str) -> bool {
    crate::cmd::dispatch_auto_has_prog(prog)
        || crate::cmd::dispatch_named_has_prog(prog)
        || FILTER_ARM_PROGS.contains(&prog)
}

/// True iff this exact `<prog> <sub>` already has its own compaction route.
///
/// [`knows_program`] answers a coarser question and cannot stand in for this
/// one: `git` is one of the most heavily covered programs in the product, so
/// "does git have a compactor" is always yes while `git ls-files` may still be
/// uncovered — and, the other way round, a `git status` that happened to route
/// generically (piped, chained, or simply out-compacted by the generic pass)
/// is not a coverage gap at all. Advice built on the program name alone gets
/// both cases wrong.
///
/// Programs with no subcommand at all (`ls`, `grep`) are covered by
/// [`knows_program`]; this returns false for them, which is what the caller
/// wants — there is no finer route to point at.
pub fn knows_subcommand(prog: &str, sub: &str) -> bool {
    !sub.is_empty()
        && FILTER_ARM_PAIRS
            .iter()
            .any(|(p, s)| *p == prog && *s == sub)
}

/// What to name when a run compacted only generically — or `None` when there
/// is nothing worth naming.
///
/// `None` means "this is not a coverage gap": the exact route already exists
/// and the generic pass simply won or never got the chance (a pipe, a chain).
/// Otherwise the returned name is as specific as the dispatch itself, so a
/// gap in `git ls-files` is reported as `git ls-files` and never as `git`.
pub fn uncovered_route_name(argv: &[String]) -> Option<String> {
    let prog = program_basename(argv);
    if prog.is_empty() {
        return None;
    }
    // A token that affects the SHELL rather than producing output can never
    // have a compactor, so naming it is advice for work nobody can do.
    // `segment_must_not_be_wrapped` is exactly that set — `cd`, `export`,
    // `set`, `continue`, `true`, `:` — so it is asked rather than listed again.
    //
    // It reaches here through an UNPARSABLE chain. `meaningful_segment` skips a
    // leading state-modifier, but only when the chain splits: give it
    // `cd /repo && python3 - <<'PY' … PY` and `chain_shape` answers `Unparsed`,
    // the whole string comes back, and the first token is `cd`. Field proof
    // from `~/.tokenade/cmdstats` on this machine: `cd.nudged` had fired, and
    // the message reached the agent — "'cd' has run 26× recently with only
    // generic compaction. A command-specific compactor would cut its output".
    // `cd` has no output to cut.
    if crate::command_rewrite::segment_must_not_be_wrapped(&prog) {
        return None;
    }
    // And a token that cannot be a program at all. The same unparsable chains
    // that leave a `cd` in the program position also leave `done;`, `{`,
    // `clean(){`, `$B` and a bare `-t` there, and this name is written as a
    // FILENAME under `~/.tokenade/cmdstats/` and quoted back to the agent.
    // Measured over 25 515 real commands: 128 of 219 distinct names were not
    // programs, 839 of 3 431 occurrences.
    if !crate::command_rewrite::is_plausible_program_name(&prog) {
        return None;
    }
    // A LABEL is not a program either, and it reaches here the same way `cd`
    // does — through a chain nothing could split. `echo "=== section ==="; cat
    // big.txt` leaves `echo` in the program position, and `echo` prints back
    // exactly what the caller typed: there is nothing a compactor could cut.
    // `meaningful_segment` has skipped this set since the routing fix; the
    // nudge asked the OTHER list (`segment_must_not_be_wrapped`), which is
    // about subshell safety and does not contain `echo`, `printf` or `sleep`.
    // Field proof from `~/.tokenade/cmdstats` on this machine 2026-09-05:
    // `echo.count` was accumulating toward a nudge that can only ask for
    // impossible work.
    if crate::command_rewrite::segment_is_a_label(&prog) {
        return None;
    }
    // And the name has to be something the shell could actually RUN. The
    // guards above reject a token that cannot be a program by SHAPE; they say
    // nothing about whether this particular one exists. Same field proof, same
    // day: `SI.count` 5 with `SI.nudged` already written — the user was told to
    // write a compactor for `SI` — plus `file_searchrs` (the file
    // `file_search.rs` in program position) and `cargo_nt`. A missing nudge
    // costs nothing; a nudge naming something unrunnable is advice nobody can
    // act on, and it is written into `cmdstats` as a filename too.
    //
    // Resolution is cached, and a program tokenade already knows is let
    // through below on its own name rather than on `$PATH` — a compactor that
    // ships in the binary is proof enough that the program is real.
    //
    // A program given by PATH — `/opt/tools/bin/frobnicate` — is resolved on
    // the token the caller wrote, not on the basename `program_basename`
    // returns, or a tool living outside `$PATH` would lose its nudge for
    // being spelled the way it has to be spelled.
    let written = argv
        .get(program_index(argv))
        .map(String::as_str)
        .unwrap_or("");
    let spelled_as_a_path = written.contains(['/', '\\'])
        && std::fs::metadata(written)
            .map(|m| m.is_file())
            .unwrap_or(false);
    if !spelled_as_a_path
        && !known_program_names().contains(&prog.as_str())
        && !crate::availability::is_available(&prog)
    {
        return None;
    }
    // The subcommand must be read from the program's OWN arguments, exactly as
    // `setup_filter_state` does with `argv[real_prog_idx..]`. Reading it off
    // the whole argv turned `cd x && git status` into the route name "git ."
    // — the `cd` argument mistaken for git's subcommand.
    let sub = find_subcommand(&prog, &argv[program_index(argv).min(argv.len())..]);
    if knows_subcommand(&prog, sub) {
        return None;
    }
    if !sub.is_empty()
        && crate::command_rewrite::is_plausible_program_name(sub)
        && FILTER_ARM_PAIRS.iter().any(|(p, _)| *p == prog)
    {
        return Some(format!("{prog} {sub}"));
    }
    // A program tokenade already compacts is not a gap, even when THIS run
    // routed generically. `knows_subcommand` deliberately answers `false` for
    // the subcommand-less programs (`cat`, `ls`, `grep`, `sed`, `python`, …),
    // and until 2026-08-04 nothing asked the coarser question afterwards — so
    // all 211 of them were reported as missing. Field proof from
    // `~/.tokenade/cmdstats`: `cat.nudged`, `ls.nudged`, `grep.nudged`,
    // `sed.nudged`, `python.nudged` had all fired, each telling the user to
    // write a compactor that ships in the binary.
    if knows_program(&prog) {
        return None;
    }
    Some(prog)
}

/// Every program name [`knows_program`] accepts — sorted, deduped. Used by
/// the shell proxy's `--all` mode; prefer the predicate for membership tests.
pub fn known_program_names() -> Vec<&'static str> {
    let mut v: Vec<&'static str> = crate::cmd::AUTO_DISPATCH_PROGS
        .iter()
        .chain(crate::cmd::NAMED_EXTRA_PROGS)
        .chain(FILTER_ARM_PROGS)
        .copied()
        .collect();
    v.sort_unstable();
    v.dedup();
    v
}
